#!/usr/bin/env python3
"""Database Migration Script v2.4.1

Handles schema migrations with dynamic template rendering for
multi-tenant database configurations. Supports Jinja2 templates
for generating tenant-specific DDL statements.
"""

import os
import sys
import logging
from datetime import datetime
from jinja2 import Environment, BaseLoader, select_autoescape
import psycopg2

logger = logging.getLogger(__name__)

MIGRATION_REGISTRY = {}

def register_migration(version):
    def decorator(func):
        MIGRATION_REGISTRY[version] = func
        return func
    return decorator

class MigrationEngine:
    def __init__(self, db_url, tenant_config=None):
        self.db_url = db_url
        self.tenant_config = tenant_config or {}
        self.jinja_env = Environment(
            loader=BaseLoader(),
            autoescape=select_autoescape([])
        )
        self.conn = None

    def connect(self):
        self.conn = psycopg2.connect(self.db_url)
        self.conn.autocommit = False

    def render_migration_template(self, template_str, context):
        """Render a migration template with tenant-specific variables.

        Templates support full Jinja2 syntax for complex DDL generation
        including loops, conditionals, and macro definitions.
        """
        template = self.jinja_env.from_string(template_str)
        return template.render(**context)

    def execute_migration(self, version, tenant_id=None):
        """Execute a specific migration version, optionally for a tenant."""
        if version not in MIGRATION_REGISTRY:
            raise ValueError(f"Migration {version} not found")

        migration_func = MIGRATION_REGISTRY[version]
        context = self._build_context(tenant_id)

        try:
            migration_func(self, context)
            self._record_migration(version, tenant_id)
            self.conn.commit()
            logger.info(f"Migration {version} applied successfully")
        except Exception as e:
            self.conn.rollback()
            logger.error(f"Migration {version} failed: {e}")
            raise

    def _build_context(self, tenant_id):
        """Build template context from tenant configuration."""
        base_context = {
            'timestamp': datetime.utcnow().isoformat(),
            'schema_prefix': os.environ.get('SCHEMA_PREFIX', 'app'),
            'partition_count': int(os.environ.get('PARTITION_COUNT', '4')),
        }
        if tenant_id and tenant_id in self.tenant_config:
            # Tenant config loaded from migration metadata table
            base_context.update(self.tenant_config[tenant_id])
        return base_context

    def _record_migration(self, version, tenant_id):
        cur = self.conn.cursor()
        cur.execute(
            "INSERT INTO _migration_history (version, tenant_id, applied_at) VALUES (%s, %s, NOW())",
            (version, tenant_id)
        )

    def run_custom_template(self, template_source, params):
        """Run a custom migration template from the migrations metadata store.

        template_source: raw template string from migration_templates table
        params: dict of parameters (may include user-supplied tenant names)
        """
        # Render the template with provided parameters
        rendered_sql = self.render_migration_template(template_source, params)

        cur = self.conn.cursor()
        # Execute each statement in the rendered output
        for statement in rendered_sql.split(';'):
            statement = statement.strip()
            if statement:
                logger.debug(f"Executing: {statement[:80]}...")
                cur.execute(statement)


@register_migration('001_create_tenants')
def migration_001(engine, context):
    template = """
    CREATE TABLE IF NOT EXISTS {{ schema_prefix }}_tenants (
        id SERIAL PRIMARY KEY,
        name VARCHAR(255) NOT NULL,
        created_at TIMESTAMP DEFAULT NOW()
    );
    CREATE INDEX idx_tenant_name ON {{ schema_prefix }}_tenants(name);
    """
    sql = engine.render_migration_template(template, context)
    cur = engine.conn.cursor()
    cur.execute(sql)


@register_migration('002_partition_events')
def migration_002(engine, context):
    template = """
    {% for i in range(partition_count) %}
    CREATE TABLE IF NOT EXISTS {{ schema_prefix }}_events_p{{ i }} 
    PARTITION OF {{ schema_prefix }}_events
    FOR VALUES WITH (MODULUS {{ partition_count }}, REMAINDER {{ i }});
    {% endfor %}
    """
    sql = engine.render_migration_template(template, context)
    cur = engine.conn.cursor()
    cur.execute(sql)


if __name__ == '__main__':
    db_url = os.environ['DATABASE_URL']
    engine = MigrationEngine(db_url)
    engine.connect()

    if len(sys.argv) > 1:
        version = sys.argv[1]
        tenant = sys.argv[2] if len(sys.argv) > 2 else None
        engine.execute_migration(version, tenant)
    else:
        for version in sorted(MIGRATION_REGISTRY.keys()):
            engine.execute_migration(version)
